async function syncFromSupabase() {
  if (typeof supabaseClientInstance === 'undefined' || !supabaseClientInstance) {
    console.log("Supabase client not initialized. Using offline mode.");
    return;
  }
  try {
    console.log("Attempting to sync state from Supabase cloud...");
    const { data, error } = await supabaseClientInstance
      .from('user_data')
      .select('state')
      .eq('user_id', 'default_cadet')
      .maybeSingle();
      
    if (error) {
      console.error("Supabase load error:", error.message);
      return;
    }
    
    if (data && data.state) {
      console.log("Found cloud state. Merging state...");
      const cloudState = data.state;
      
      const localDate = STATE.lastActiveDate ? new Date(STATE.lastActiveDate) : new Date(0);
      const cloudDate = cloudState.lastActiveDate ? new Date(cloudState.lastActiveDate) : new Date(0);
      
      if (localDate > cloudDate) {
        cloudState.streak = STATE.streak;
        cloudState.lastActiveDate = STATE.lastActiveDate;
      } else if (localDate.getTime() === cloudDate.getTime()) {
        cloudState.streak = Math.max(STATE.streak, cloudState.streak || 0);
      }
      
      const mergedSyllabus = { ...(STATE.syllabusProgress || {}), ...(cloudState.syllabusProgress || {}) };
      const mergedExpandedNotes = { ...(STATE.aiExpandedNotes || {}), ...(cloudState.aiExpandedNotes || {}) };
      const mergedWeaknessStats = { ...(STATE.weaknessStats || {}), ...(cloudState.weaknessStats || {}) };
      const mergedSrsData = { ...(STATE.srsData || {}), ...(cloudState.srsData || {}) };
      
      let mergedCbtScores = [...(STATE.cbtScores || [])];
      (cloudState.cbtScores || []).forEach(cloudScore => {
        const exists = mergedCbtScores.find(localScore => 
          localScore.date === cloudScore.date && localScore.examTitle === cloudScore.examTitle
        );
        if (!exists) mergedCbtScores.push(cloudScore);
      });
      
      let mergedFormulas = [...new Set([...(STATE.readFormulasList || []), ...(cloudState.readFormulasList || [])])];
      
      STATE = { 
        ...STATE, 
        ...cloudState,
        syllabusProgress: mergedSyllabus,
        aiExpandedNotes: mergedExpandedNotes,
        weaknessStats: mergedWeaknessStats,
        srsData: mergedSrsData,
        cbtScores: mergedCbtScores,
        readFormulasList: mergedFormulas,
        readFormulasCount: mergedFormulas.length
      };
      
      checkStreak();
      
      localStorage.setItem("tac_revise_state_v1", JSON.stringify(STATE));
      updateDashboardMetrics();
      
      // Auto-save the newly checked streak back to cloud
      await syncToSupabase();
      console.log("Cloud sync complete!");
    } else {
      console.log("No cloud state found. Initializing cloud database with current local state...");
      await syncToSupabase();
    }
  } catch (err) {
    console.error("Failed to sync from Supabase:", err);
  }
}

async function syncToSupabase() {
  if (typeof supabaseClientInstance === 'undefined' || !supabaseClientInstance) {
    return;
  }
  try {
    const { error } = await supabaseClientInstance
      .from('user_data')
      .upsert({ 
        user_id: 'default_cadet', 
        state: STATE, 
        updated_at: new Date().toISOString() 
      }, { onConflict: 'user_id' });
      
    if (error) {
      console.error("Supabase upsert error:", error.message);
    } else {
      console.log("Cloud state auto-saved to Supabase.");
    }
  } catch (err) {
    console.error("Failed to auto-save to Supabase:", err);
  }
}

function initAppState() {
  const localData = localStorage.getItem("tac_revise_state_v1");
  if (localData) {
    try {
      STATE = { ...STATE, ...JSON.parse(localData) };
    } catch (e) {
      console.error("Error loading localStorage state:", e);
    }
  }
  STATE.aiExpandedNotes = STATE.aiExpandedNotes || {};
  
  checkStreak();
  localStorage.setItem("tac_revise_state_v1", JSON.stringify(STATE));
  updateDashboardMetrics();
  
  checkCurrentAffairsExpiry();
  
  // Trigger async cloud database sync
  syncFromSupabase();
}

function saveState() {
  localStorage.setItem("tac_revise_state_v1", JSON.stringify(STATE));
  updateDashboardMetrics();
  
  // Trigger async cloud database save
  syncToSupabase();
}

function checkStreak() {
  const now = new Date();
  const todayStr = now.toDateString();
  
  if (!STATE.lastActiveDate) {
    STATE.streak = 1;
    STATE.lastActiveDate = todayStr;
  } else if (STATE.lastActiveDate !== todayStr) {
    const lastDate = new Date(STATE.lastActiveDate);
    const todayDate = new Date(todayStr);
    
    // Normalize time to noon to prevent Daylight Saving Time edge cases
    lastDate.setHours(12, 0, 0, 0);
    todayDate.setHours(12, 0, 0, 0);
    
    const diffTime = todayDate.getTime() - lastDate.getTime();
    const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24));
    
    if (diffDays === 1) {
      STATE.streak += 1;
    } else if (diffDays > 1 || diffDays < 0) {
      STATE.streak = 1;
    }
    STATE.lastActiveDate = todayStr;
  }
}

function checkCurrentAffairsExpiry() {
  const currentYear = new Date().getFullYear();
  const lastCheckedYear = localStorage.getItem("tac_ca_year_check");
  
  if (lastCheckedYear && parseInt(lastCheckedYear) < currentYear) {
    console.log("New calendar year detected. Wiping local Current Affairs metrics.");
    localStorage.setItem("tac_ca_year_check", currentYear.toString());
  } else if (!lastCheckedYear) {
    localStorage.setItem("tac_ca_year_check", currentYear.toString());
  }
}

function updateDashboardMetrics() {
  document.getElementById("stat-streak").innerText = STATE.streak + " Days";
  
  const totalTopics = SYLLABUS_DATABASE.reduce((sum, exam) => sum + exam.topics.length, 0);
  let completedTopics = 0;
  for (const topicId in STATE.syllabusProgress) {
    if (STATE.syllabusProgress[topicId] === 'completed') {
      completedTopics++;
    }
  }
  const syllabusPct = totalTopics > 0 ? Math.round((completedTopics / totalTopics) * 100) : 0;
  document.getElementById("stat-syllabus").innerText = syllabusPct + "%";
  
  document.getElementById("stat-formulas").innerText = STATE.readFormulasCount;
  
  if (STATE.cbtScores.length > 0) {
    const totalPct = STATE.cbtScores.reduce((sum, record) => sum + (record.score / record.maxScore), 0);
    const avgPct = Math.round((totalPct / STATE.cbtScores.length) * 100);
    document.getElementById("stat-cbt-avg").innerText = avgPct + "%";
  } else {
    document.getElementById("stat-cbt-avg").innerText = "0%";
  }
  
  // Tactical XP and Military Rank Calculation
  const streakXp = (STATE.streak || 0) * 100;
  const syllabusXp = completedTopics * 150;
  const cbtXp = (STATE.cbtScores || []).reduce((sum, r) => sum + Math.round((r.score / r.maxScore) * 1000), 0) + ((STATE.cbtScores || []).length * 500);
  const formulaXp = (STATE.readFormulasCount || 0) * 50;
  const totalXp = streakXp + syllabusXp + cbtXp + formulaXp;

  const branch = STATE.branch || 'army';
  const branchRanks = RANK_SYSTEM[branch] || RANK_SYSTEM.army;
  const XP_THRESHOLDS = [0, 1000, 2500, 5000, 10000, 20000, 35000, 50000];
  
  const RANKS = branchRanks.map((r, idx) => ({
    name: r.rank,
    min: XP_THRESHOLDS[idx] || (idx * 10000)
  }));

  let currentRankIndex = 0;
  for (let i = 0; i < RANKS.length; i++) {
    if (totalXp >= RANKS[i].min) {
      currentRankIndex = i;
    }
  }
  const currentRank = RANKS[currentRankIndex];
  const nextRank = RANKS[currentRankIndex + 1] || null;
  
  let pctProgress = 100;
  if (nextRank) {
    const range = nextRank.min - currentRank.min;
    const currentProgress = totalXp - currentRank.min;
    pctProgress = Math.round((currentProgress / range) * 100);
  }

  const rankEl = document.getElementById("profile-rank");
  if (rankEl) {
    rankEl.innerText = `${currentRank.name} (${totalXp.toLocaleString()} XP)`;
  }
  
  const branchEl = document.getElementById("profile-branch");
  if (branchEl) {
    if (nextRank) {
      branchEl.innerText = `Next: ${nextRank.name} at ${nextRank.min.toLocaleString()} XP`;
    } else {
      branchEl.innerText = `Max Rank Achieved`;
    }
  }

  const xpBarEl = document.getElementById("profile-xp-bar");
  if (xpBarEl) {
    xpBarEl.style.width = pctProgress + "%";
  }
  
  // Update medals list
  renderDashboardMedals(syllabusPct);

  renderDashboardRecentCBT();
  if (typeof renderDashboardWeaknessHeatmap === 'function') renderDashboardWeaknessHeatmap();
  if (typeof updateDashboardSrsQueue === 'function') updateDashboardSrsQueue();
}

function renderDashboardMedals(syllabusPct) {
  const container = document.getElementById("dashboard-medals-grid");
  if (!container) return;

  const MEDALS = [
    { id: 'iron-grit', name: 'Iron Grit', emoji: '🛡️', desc: 'Maintain a study streak of 3 or more days.', unlocked: (STATE.streak >= 3) },
    { id: 'marksman', name: 'Marksman', emoji: '🎯', desc: 'Score 80% or higher on any CBT Mock Exam.', unlocked: (STATE.cbtScores && STATE.cbtScores.some(r => (r.score / r.maxScore) >= 0.8)) },
    { id: 'syllabus-vet', name: 'Syllabus Vet', emoji: '🎗️', desc: 'Master 10% or more of the total syllabus.', unlocked: (syllabusPct >= 10) },
    { id: 'elite-scholar', name: 'Elite Scholar', emoji: '📜', desc: 'Memorize 5 or more high-yield formulas.', unlocked: (STATE.readFormulasCount >= 5) },
    { id: 'tactical-pioneer', name: 'Pioneer', emoji: '🚀', desc: 'Complete at least 1 CBT Mock Exam.', unlocked: (STATE.cbtScores && STATE.cbtScores.length >= 1) }
  ];

  let html = '';
  MEDALS.forEach(medal => {
    html += `
      <div class="medal-badge ${medal.unlocked ? 'unlocked' : ''}" id="medal-${medal.id}">
        <div class="medal-icon">${medal.emoji}</div>
        <div class="medal-name">${medal.name}</div>
        <div class="medal-desc">
          **${medal.name}**<br/>
          ${medal.desc}<br/>
          <span style="color: ${medal.unlocked ? '#4ade80' : '#ef4444'}; font-weight: bold; font-size: 0.65rem;">
            ${medal.unlocked ? 'UNLOCKED' : 'LOCKED'}
          </span>
        </div>
      </div>
    `;
  });
  container.innerHTML = html;
}


function renderDashboardRecentCBT() {
  const container = document.getElementById("dashboard-recent-cbt");
  if (STATE.cbtScores.length === 0) {
    container.innerHTML = `<p style="color:var(--text-muted);">No tests taken yet. Launch CBT Mock Test Hub to start your revision.</p>`;
    return;
  }
  
  let html = `<ul style="list-style:none; display:flex; flex-direction:column; gap:10px;">`;
  const recent = STATE.cbtScores.slice(-3).reverse();
  recent.forEach(r => {
    const pct = Math.round((r.score / r.maxScore) * 100);
    html += `
      <li style="display:flex; justify-content:space-between; align-items:center; background-color:rgba(255,255,255,0.02); padding:8px 12px; border-radius:6px; border:1px solid var(--border);">
        <div>
          <strong style="font-size:0.85rem;">r.examTitle**
          <div style="font-size:0.75rem; color:var(--text-muted);">{r.date}</div>
        </div>
        <div style="font-family:var(--font-mono); font-weight:bold; color:pct >= 50 ? 'var(--accent)' : 'var(--danger)'">
          {r.score}/r.maxScore ({pct}%)
        </div>
      </li>
    `;
  });
  html += `</ul>`;
  container.innerHTML = html;
}

